export function escapeHTML(value) {
  if (value === null || value === undefined) return "-";
  const div = document.createElement("div");
  div.appendChild(document.createTextNode(String(value)));
  return div.innerHTML;
}

export function safeOpenExternal(rawUrl) {
  const parsed = new URL(rawUrl, window.location.origin);
  if (parsed.protocol !== "https:") {
    throw new Error("Blocked non-HTTPS URL");
  }

  window.open(parsed.toString(), "_blank", "noopener,noreferrer");
}

export function toIsoOrNullFromDatetimeLocal(value) {
  if (!value) return null;
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return null;
  return date.toISOString();
}

export function toDatetimeLocal(value) {
  if (!value) return "";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "";

  const pad = (num) => String(num).padStart(2, "0");
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}`;
}

export function formatDateTime(value) {
  if (!value) return "-";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "-";
  return date.toLocaleString();
}

export function normalizeListPayload(data, keys = []) {
  if (Array.isArray(data)) return data;

  for (const key of keys) {
    if (data && Array.isArray(data[key])) return data[key];
  }

  if (data && Array.isArray(data.data)) return data.data;
  return [];
}

export function normalizeUsersPayload(data) {
  return normalizeListPayload(data, ["users", "Users"]);
}

export function readObjectValue(source, keys, fallback = "") {
  for (const key of keys) {
    if (source && source[key] !== undefined && source[key] !== null) return source[key];
  }
  return fallback;
}

export function getSettingsRecord(data) {
  if (Array.isArray(data)) return data[0] || {};
  if (data && Array.isArray(data.settings)) return data.settings[0] || {};
  if (data && Array.isArray(data.Settings)) return data.Settings[0] || {};
  if (data && data.data && !Array.isArray(data.data) && typeof data.data === "object") return data.data;
  if (data && typeof data === "object") return data;
  return {};
}

export function toggleControlVisibility(element, shouldShow, visibleClass = "d-inline-flex") {
  if (!element) return;
  element.classList.toggle("d-none", !shouldShow);
  element.classList.toggle(visibleClass, shouldShow);
}
